  ('30000000-0000-4000-8000-000000000031'::uuid, '20000000-0000-4000-8000-000000000003'::uuid, 'Warp / Weft / Wait', 2025, 'textile', array['reclaimed industrial thread', 'hand-dyed wool', 'cedar batten']::text[], 180, 95, 6, 'cm', 'A dress built from hundreds of hand-stitched feathers over a printed ground. It changes as it is touched; the quills lift and settle.', 'available', '© June Takahashi-Bell. Touching encouraged.', 2600, 'CAD', 'public', 'public', array['wall hanging', 'tactile', 'wool']::text[], '2026-08-17T12:00:00.000Z'::timestamptz, '2026-08-02T12:00:00.000Z'::timestamptz, '2026-08-27T12:00:00.000Z'::timestamptz),
